float sphereRadius = 0.7;
vec3 sphereColor = vec3(0.5, 0.5, 1);
vec3 ambientColor = vec3(0.9, 0.3, 0.4);
vec3 highlightColor = vec3(1, 1, 1);
float highlightFactor = 100.0;
vec3 lightPos = vec3(0);


void render(out vec4 fragColor, vec2 scaledCoord);
vec3 getNormal(vec2 scaledCoord);
vec2 scaledCoord(vec2 fragCoord);
bool checkInRadius(vec2 scaledCoord, float sphereRadius);


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    fragColor = vec4(0);
    vec2 sC = scaledCoord(fragCoord);

    lightPos = vec3(cos(iTime), 0.5, sin(iTime));

    if (checkInRadius(sC, sphereRadius)) {
        render(fragColor, sC);
    }
}

void render(out vec4 fragColor, vec2 scaledCoord) {
    vec3 normal = getNormal(scaledCoord);
    float lightFactor = clamp(dot(normal, normalize(lightPos)), 0.0, 1.0);

    vec3 litColor = sphereColor * lightFactor;
    vec3 ambColor = sphereColor * ambientColor * (1.0-lightFactor);
    vec3 highlight = highlightColor * pow(lightFactor, highlightFactor);

    fragColor = vec4(ambColor + litColor + highlight, 1);
}

vec3 getNormal(vec2 scaledCoord) {
    return normalize(vec3(
        scaledCoord.x,
        scaledCoord.y,
        -sqrt(pow(sphereRadius, 2.0) - pow(scaledCoord.x, 2.0) - pow(scaledCoord.y, 2.0))
    ));
}

vec2 scaledCoord(vec2 fragCoord) {
    return (fragCoord - iResolution.xy/2.0) / (iResolution.y/2.0);
}

bool checkInRadius(vec2 scaledCoord, float sphereRadius) {
    if (distance(scaledCoord, vec2(0,0)) < sphereRadius)
        return true;

    return false;
}
